C10 = [
("s2","Wat is tegenkoppeling?","Een deel van het uitgangssignaal komt in tegenfase terug op de ingang. De versterking wordt kleiner, maar de lineariteit beter en de vervorming kleiner."),
("s2","Wat is meekoppeling (positieve terugkoppeling)?","Een deel van het uitgangssignaal komt in fase terug op de ingang. Dat kan de versterking groter maken, of tot oscillatie leiden."),
("s2","Welke drie voorwaarden gelden voor een oscillator?","Een versterkend element, terugkoppeling in fase en een rondgaande versterking van minstens 1."),
("s2","Hoe groot is de rondgaande versterking in een stabiel werkende oscillator?","Precies 1. Aan het begin is hij groter dan 1, tot de amplitude zichzelf begrenst."),
("s2","Hoe komt een oscillator op gang?","Door ruis: die bevat alle frequenties, ook die van de afgestemde kring. Die wordt versterkt en teruggekoppeld."),
("s2","Hoe begrenst een oscillator zijn eigen amplitude?","Het element wordt door de groter wordende amplitude in klasse C getrokken (gelijkrichting), waardoor de versterking daalt tot de rondgaande versterking 1 is."),
("s3","Wat zijn de eigenschappen van een ideale opamp?","Versterking oneindig, ingangsimpedantie oneindig, uitgangsimpedantie 0 en bandbreedte van 0 tot oneindig."),
("s3","Hoe groot is de uitgangsimpedantie van een ideale opamp?","Nul."),
("s3","Hoe groot is de open-lusversterking van een praktische opamp (741)?","Bij gelijkspanning en heel lage frequenties ongeveer 10⁵ tot 10⁶; bij 1 kHz ongeveer 1000 en bij 1 MHz ongeveer 1."),
("s3","Wat is bij een opamp vrijwel constant?","Het product van versterking en bandbreedte."),
("s3","Welke ingangen heeft een opamp?","Een inverterende (−) en een niet-inverterende (+) ingang. De uitgang is in fase met de + ingang en in tegenfase met de − ingang."),
("s3","Welke voeding heeft een opamp meestal?","Een symmetrische voeding, bijvoorbeeld +15 V en −15 V. De uitgangsspanning blijft ongeveer 5 V onder de voedingsspanning."),
("s3","Wat geldt voor de spanningen op de ingangen van een tegengekoppelde opamp?","De spanning op de − ingang is (vrijwel) gelijk aan die op de + ingang."),
("s3","Wat is de versterking van een inverterende opamp?","Au = −R2 / R1, met R1 in serie met de ingang en R2 als tegenkoppelweerstand."),
("s3","Wat is de versterking van een niet-inverterende opamp?","Au = 1 + R2 / R1: R2 als tegenkoppelweerstand, R1 van de − ingang naar massa."),
("s3","Wat is een spanningsvolger met een opamp?","Een opamp met de uitgang direct op de − ingang. Au = 1, ingangsimpedantie zeer hoog, uitgangsimpedantie zeer laag."),
("s3","Waarvoor gebruik je een spanningsvolger?","Als buffer: een bron met hoge impedantie sturen zonder belasting."),
("s3","Hoe groot is de uitgangsspanning van een optelversterker?","Uuit = −(U1/R1 + U2/R2 + U3/R3) · R4. Bij gelijke weerstanden Uuit = −(U1 + U2 + U3)."),
("s3","Hoe werkt een verschilversterker?","Uuit = (R2/R1) · (U2 − U1). Bij vier gelijke weerstanden Uuit = U2 − U1."),
("s3","Wat doet een opamp zonder tegenkoppeling (comparator)?","Hij vergelijkt Uin met Uref: de uitgang staat op bijna de positieve of negatieve voedingsspanning, afhankelijk van welke ingang hoger is."),
("s3","Wat maakt een opamp met een condensator in de ingangsleiding en weerstand tegenkoppeling?","Een hoogdoorlaatfilter: lage frequenties worden niet doorgelaten."),
("s5","Wat is een Meissner- of Armstrong-oscillator?","Een LC-oscillator waarbij de terugkoppeling via een inductieve koppeling (aparte wikkeling) plaatsvindt; de wikkelrichting (stippen) zorgt voor de goede fase."),
("s5","Wat is een Hartley-oscillator?","Een LC-oscillator waarbij de terugkoppeling via een aftakking op de spoel gaat."),
("s5","Wat is een Colpitts-oscillator?","Een LC-oscillator waarbij de terugkoppeling via een capacitieve spanningsdeler (aftakking tussen twee condensatoren) gaat."),
("s5","Hoe onthoud je Hartley en Colpitts?","Colpitts begint met C: condensatoren. Hartley begint met H: de spoel (inductantie)."),
("s5","Wat is een Clapp-oscillator?","Een Colpitts-oscillator met in serie met de spoel een extra variabele condensator C5. De frequentie wordt vrijwel alleen door L en C5 bepaald."),
("s5","Wat is een Seiler-oscillator?","Een variant van Clapp waarbij C5 over de hele spoel staat."),
("s5","Welke schakelingen met een transistor zijn in fase en dus als oscillator geschikt?","Gemeenschappelijke drain, collector en anode (GDS, GCS, GAS) en gemeenschappelijke gate, basis en rooster (GGS, GBS, GRS)."),
("s5","Welke schakelingen draaien de fase 180° en hebben dus extra faseverschuiving nodig?","GSS, GES en GKS (gemeenschappelijke source, emitter, kathode). Die is te maken met een aftakking op de geaarde kring."),
("s5","Hoe groot is de resonantiefrequentie van een LC-kring?","f = 1 / (2π √(L·C))."),
("s5","Welke eisen worden aan een HF-oscillator gesteld?","Constante frequentie en weinig harmonischen."),
("s5","Hoe verbeter je de frequentiestabiliteit van een oscillator?","Het element los koppelen aan de kring (aftakking), hoge Q, warmteontwikkeling beperken, een stevige mechanische opbouw en een gestabiliseerde voedingsspanning."),
("s5","Wat is een VCO?","Een spanningsgestuurde oscillator (voltage controlled oscillator). Bijvoorbeeld met een capaciteitsdiode (varicap) in de kring."),
("s5","Hoe verstem je een oscillator elektrisch?","Met een capaciteitsdiode (varicap): een stuurspanning, via een grote weerstand toegevoerd, verandert zijn capaciteit."),
("s5","Wat is een vrijlopende oscillator?","Een oscillator waarvan de frequentie door een LC-kring wordt bepaald, zonder kristal."),
("s6","Waarom gedraagt een kwartskristal zich als LC-kring?","Door het piëzo-elektrisch effect: een wisselspanning laat het kristal mechanisch trillen en omgekeerd."),
("s6","Welke resonanties heeft een kwartskristal?","Een serieresonantie en een parallelresonantie, dicht bij elkaar."),
("s6","Wanneer is een kristal inductief?","Tussen serieresonantie en parallelresonantie. Buiten dat gebied is het capacitief."),
("s6","Wat is het vervangingsschema van een kwartskristal?","Een serieschakeling van L, C en R, met daarnaast de houdercapaciteit parallel."),
("s6","Wat is een Pierce-oscillator?","Een kristaloscillator met het kristal tussen gate en drain en een trimcondensator voor kleine frequentiecorrectie."),
("s6","Wat is een overtone-oscillator?","Een kristaloscillator die niet op de grondtoon, maar op een oneven harmonische (meestal 3e of 5e) van het kristal werkt."),
("s6","Hoe dwing je een overtone-oscillator naar de overtone?","Met een afgestemde kring in het draincircuit die op de overtone is afgestemd."),
("s6","Wat is een Miller-oscillator?","Een kristal in het gatecircuit en een LC-kring in het draincircuit. De terugkoppeling loopt via de capaciteit tussen gate en drain."),
("s6","Wat is het Miller-effect?","Een capaciteit tussen uitgang en ingang van een versterker lijkt aan de ingang (Au + 1) keer zo groot."),
("s6","Waarom werkt een Miller-oscillator niet met een dual-gate MOSFET of penthode?","Het schermrooster (gate 2) blokkeert de capacitieve verbinding tussen drain en gate 1."),
("s6","Wat bepaalt de frequentie in een kristaloscillator?","Het kristal: de serie- of parallelresonantie, afhankelijk van de schakeling."),
("s8","Wat is een parasitaire oscillator?","Een onbedoelde oscillatie in een versterkende schakeling, doordat ongewenste terugkoppeling optreedt."),
("s8","Hoe voorkom je parasitaire oscillaties?","Niet meer versterken dan nodig is (tegenkoppeling), signaalleidingen niet parallel leggen, trappen afschermen en voedingsleidingen ontkoppelen."),
("s10","Wat is faseruis?","De ene periode van een oscillator is net iets korter of langer dan de volgende: het signaal wiebelt een beetje."),
("s10","Wat zegt veel faseruis over een oscillator?","Dat hij van mindere kwaliteit is."),
("s11","Hoe stabiliseer je een spanning met een zenerdiode?","Een serieweerstand Rs en de zenerdiode parallel aan de belasting. De zenerdiode neemt de stroom die de belasting niet gebruikt."),
("s11","Wat is de voorwaarde voor een zenerstabilisatie?","Iin moet groter zijn dan Iuit, zodat er altijd stroom overblijft voor de zenerdiode, en Uin > Uuit."),
("s11","Hoe bereken je de serieweerstand Rs van een zenerstabilisatie?","Rs = (Uin − Uz) / (Ibel + Iz), met Iz de minimale zenerstroom."),
("s11","Hoe groot is de dissipatie in de zenerdiode?","P = Uz · Iz. De maximale dissipatie treedt op als de belasting weinig of niets afneemt."),
("s11","Waarom zet je een emittervolger achter een zenerdiode?","Zo kan de schakeling veel meer stroom leveren: de uitgangsstroom is hFE keer de stroom uit de zenerdiode."),
("s11","Hoeveel lager is de uitgang van een zenerstabilisator met één emittervolger?","Ongeveer 0,6 V (één basis-emitterspanning van een siliciumtransistor) lager dan de zenerspanning."),
("s11","Wat is een Darlingtonschakeling?","Twee transistoren als emittervolger in serie. De stroomversterking is het product van beide; de uitgang is circa 1,2 V lager dan de zenerspanning."),
("s11","Hoe werkt een tegengekoppelde voeding?","Een spanningsdeler over de uitgang wordt vergeleken met een referentie (zenerdiode). Een afwijking regelt via de tegenkoppellus de basis van de vermogenstransistor bij."),
("s11","Hoeveel hoger moet Uin zijn dan Uuit bij een lineaire voeding?","Minimaal de zenerspanning plus 1,5 à 2 V voor de transistoren."),
("s11","Hoe maak je een regelbare voeding?","Met een potentiometer (met weerstanden aan beide kanten) in de spanningsdeler over de uitgang."),
("s11","Hoe groot is het rendement van een lineaire voeding gemiddeld?","Ongeveer 50%: de rest wordt in de serie-regelaar warmte."),
("s11","Wat betekenen de reeksen 78xx en 79xx?","Geïntegreerde spanningsstabilisatoren met vaste spanning: 78xx positief, 79xx negatief. xx is de spanning in volt (7812 = +12 V, 7915 = −15 V)."),
("s11","Hoeveel aansluitingen heeft een stabilisator met vaste spanning?","Drie: in, uit en massa (een ‘driepoot’)."),
("s12","Wat is een schakelende voeding?","Een voeding waarin de gelijkspanning met een hoogfrequente wisselspanning (10–100 kHz) en een spoel of condensatoren wordt verhoogd, verlaagd of omgekeerd."),
("s12","Welk voordeel heeft een schakelende voeding boven een lineaire?","Een hoger rendement, dus minder warmte en kleinere onderdelen (door de hoge frequentie)."),
("s12","Welk nadeel heeft een schakelende voeding?","Storing: de schakelfrequentie en zijn harmonischen komen op de uitgang en kunnen radiostoring geven."),
("s12","Wat is een ladingspomp?","Een schakeling met dioden en condensatoren en twee klokken in tegenfase die de spanning omhoog pompt, bijvoorbeeld de ladingspomp van Dickson (niet gestabiliseerd)."),
("s12","Wat is duty cycle?","De verhouding tussen pulsbreedte en periodeduur: D = tp / T, meestal in procenten. Een blokgolf heeft 50%."),
("s12","Wat is een PWM?","Een pulsbreedtemodulator: de frequentie blijft gelijk, maar de pulsbreedte (duty cycle) wordt door een regelspanning veranderd."),
("s12","Hoe regelt een PWM de uitgangsspanning?","Een stijgende uitgangsspanning maakt de pulsen smaller (kleinere duty cycle); een dalende spanning maakt ze breder."),
("s12","Welke onderdelen heeft elke PWM-voeding gemeenschappelijk?","Een spoel, een diode, een schakeltransistor en een condensator over de uitgang."),
("s12","Wat doet de spoel in een schakelende voeding?","Bij het uitschakelen van de transistor probeert hij de stroom in stand te houden: de opgeslagen magnetische energie geeft een spanningspiek en laadt de condensator op."),
("s12","Wat is een step-up converter?","Een schakelende voeding waarvan Uuit groter is dan Uin."),
("s12","Wat is een step-down converter?","Een schakelende voeding waarvan Uuit kleiner is dan Uin."),
("s12","Wat is een inverter (schakelende voeding)?","Een schakelende voeding die de polariteit omkeert: bij positieve Uin is Uuit negatief."),
("s12","Hoe herken je de inverter in het schema?","De diode staat zo dat de uitgangsspanning negatief wordt; ook de polariteit van de elco aan de uitgang is omgekeerd."),
]

